mapper.select:
SELECT /*LGVATT50040.retrieveCodeType*/ lcm.common_code as code, lcm.common_code_name as name FROM lgcom_common_code_multi_lang_c lcm ,lgcom_common_code_c lcc WHERE lcm.code_type_code = #{codeTypeCode} AND lcm.code_type_code = lcc.code_type_code AND lcm.common_code = lcc.common_code AND lcm.language_code = #{languageCode} /* session language */ AND lcc.use_flag = 'Y'
AND lcc.common_code != #{diffParam}
order by lcc.common_code asc

mapper.insert:
INSERT /*LGVATT50040.insertOtLevel*/ INTO TB_ATT_OT_LEVEL
( ot_level_id
 ,subsidiary_code					/* 해외법인코드 */
 ,time_and_attendance_yyyymm			/* 휴일년도 */
 ,shift_type_code			
 ,ot_level						
 ,lower_limit 						
 ,upper_limit 
 ,ot_category
 ,remark						
 ,creation_user_id 					/* 사용자ID */
 ,creation_date 					/* 등록일자 */
 ,last_update_user_id 				/* 최종수정자ID */
 ,last_update_date 					/* 수정일자 */
) values
( TB_ATT_OT_LEVEL_SEQ.NEXTVAL
 ,#{subsidiaryCode}
 ,#{timeAndAttendanceYyyymm}
 ,#{shiftTypeCode}
 ,#{otLevel}
 ,#{lowerLimit}
 ,#{upperLimit}
 ,#{otCategory}
 ,#{remark}
 ,#{applicationUserId}
 ,trunc(sysdate)
 ,#{applicationUserId}
 ,trunc(sysdate)
)

mapper.update:
UPDATE /*LGVATT50040.updateOtLevel*/
       TB_ATT_OT_LEVEL 
SET    shift_type_code                 = #{shiftTypeCode}             
     , ot_level                        = #{otLevel}                 
     , lower_limit                     = #{lowerLimit}
     , upper_limit                     = #{upperLimit}
     , ot_category                     = #{otCategory}
     , remark                          = #{remark}
     , last_update_user_id             = #{applicationUserId}            							/* 최종수정사용자아이디 */
     , last_update_date                = trunc(sysdate)                 							/* 최종수정일자 */
WHERE  ot_level_id                     = #{otLevelId}
